// Synthetic replica of @shopify/flash-list sources (TSX). Builds on the pure-JS
// recyclerlistview surface and renders a native AutoLayoutView host component.
import ReactNative from "react-native";
import { DataProvider, LayoutProvider } from "recyclerlistview";

const AutoLayoutView =
  (ReactNative as { requireNativeComponent?: (name: string) => unknown }).requireNativeComponent?.(
    "AutoLayoutView",
  ) ?? "AutoLayoutView";

export const FLASH_LIST_OK = "FLASH_LIST_OK";

export type FlashListProps<TItem> = {
  data: TItem[];
  renderItem: (info: { item: TItem; index: number }) => unknown;
  estimatedItemSize?: number;
};

export function FlashList<TItem>(props: FlashListProps<TItem>) {
  const dataProvider = new DataProvider((a: TItem, b: TItem) => a !== b).cloneWithRows(props.data);
  const layoutProvider = new LayoutProvider(
    () => 0,
    (_type, dimension) => {
      dimension.width = 0;
      dimension.height = props.estimatedItemSize ?? 0;
    },
  );
  return (
    <AutoLayoutView dataSize={dataProvider.getSize()} layoutProvider={layoutProvider}>
      {props.data.map((item, index) => props.renderItem({ item, index }))}
    </AutoLayoutView>
  );
}
